def find_valid_pairs(N):
    """Enumerates all valid pairs of pillar placements on an N x N grid."""
    pairs = []
    for x1 in range(1, N + 1):
        for y1 in range(1, N + 1):
            # Ensure canonical order to avoid duplicates: (x1, y1) <= (x2, y2) lexicographically
            for x2 in range(1, N + 1):
                for y2 in range(1, N + 1):
                    if x1 == x2 and y1 == y2:
                        continue

                    # Enforce ordering to count each pair only once
                    if (x1, y1) > (x2, y2):
                        continue

                    # Check validity constraint: distance >= 2 in both x and y
                    if abs(x1 - x2) >= 2 and abs(y1 - y2) >= 2:
                        pairs.append(tuple(sorted(((x1, y1), (x2, y2)))))
    return pairs

